practiceProblems.solutionCode:
public class Main {
    public static int sumMatrix(int[][] matrix) {
        int sum = 0;
        for (int r = 0; r < matrix.length; r++) {
            for (int c = 0; c < matrix[r].length; c++) {
                sum += matrix[r][c];
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        int[][] grid = {{10, 20, 30}, {5, 15, 25}};
        System.out.println("Matrix Sum: " + sumMatrix(grid));
    }
}

