public class Main {
    public static void main(String[] args) {
        int[][] pyramid = {{1}, {2, 3}, {4, 5, 6}};
        int count = 0;
        for (int r = 0; r < pyramid.length; r++) {
            for (int c = 0; c < pyramid[r].length; c++) {
                count++;
            }
        }
        System.out.println("Total Jagged Elements: " + count);
    }
}
